def fix(x):
    if isinstance(x,str):
        x=re.sub(r'\[@(\w+)\]',lambda m:f'[{num[m.group(1)]}]',x)
        x=re.sub(r'@T:(\w+)',lambda m:TK[m.group(1)],x); x=re.sub(r'@F:(\w+)',lambda m:FK[m.group(1)],x); return x
    if isinstance(x,list): return [fix(y) for y in x]
    return x
